// TestGeneratedImplicitContextRefusalsMakeNoWireCall is §27.9: every route with an implicit {org_id} or {tenant_id} refuses
// client-side when the client has resolved neither, without reaching the
// network.
func TestGeneratedImplicitContextRefusalsMakeNoWireCall(t *testing.T) {
	srv, anonymous := anonymousManagementServer(t)
	before := srv.totalCalls()
	ctx := context.Background()
	if _, err := anonymous.Organizations().Get(ctx); err == nil {
		t.Errorf("organizations.get: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.Organizations().Update(ctx, UpdateOrganizationRequest{}); err == nil {
		t.Errorf("organizations.update: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.Tenants().List(ctx, Limited(50)); err == nil {
		t.Errorf("tenants.list: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.Tenants().Create(ctx, CreateTenantRequest{Name: "example", Slug: "example"}); err == nil {
		t.Errorf("tenants.create: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.Tenants().Get(ctx, exampleID); err == nil {
		t.Errorf("tenants.get: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.Tenants().Update(ctx, exampleID, UpdateTenant{}); err == nil {
		t.Errorf("tenants.update: expected a client-side refusal with no resolved context")
	}
	if err := anonymous.Tenants().Delete(ctx, exampleID); err == nil {
		t.Errorf("tenants.delete: expected a client-side refusal with no resolved context")
	}
	if err := anonymous.Tenants().ExportAudit(ctx, exampleID); err == nil {
		t.Errorf("tenants.export_audit: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.CACertificates().List(ctx, Limited(50)); err == nil {
		t.Errorf("ca_certificates.list: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.CACertificates().Generate(ctx, CreateCACertificateRequest{KeyAlgorithm: KeyAlgorithmRsa4096, Subject: "example", ValidityDays: 1}); err == nil {
		t.Errorf("ca_certificates.generate: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.CACertificates().ImportCA(ctx, ImportCACertificateRequest{PublicCertPEM: "example"}); err == nil {
		t.Errorf("ca_certificates.import_ca: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.CACertificates().Get(ctx, exampleID); err == nil {
		t.Errorf("ca_certificates.get: expected a client-side refusal with no resolved context")
	}
	if err := anonymous.CACertificates().Revoke(ctx, exampleID); err == nil {
		t.Errorf("ca_certificates.revoke: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.CACertificates().MigrateCustody(ctx, exampleID); err == nil {
		t.Errorf("ca_certificates.migrate_custody: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.CACertificates().SetMTLSTrustAnchor(ctx, exampleID, SetMTLSTrustAnchor{Enabled: true}); err == nil {
		t.Errorf("ca_certificates.set_mtls_trust_anchor: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.CACertificates().ListSigningCas(ctx, exampleID, Limited(50)); err == nil {
		t.Errorf("ca_certificates.list_signing_cas: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.CACertificates().GenerateSigningCA(ctx, exampleID, CreateIntermediateCARequest{KeyAlgorithm: KeyAlgorithmRsa4096, ParentCAID: exampleID, Subject: "example", ValidityDays: 1}); err == nil {
		t.Errorf("ca_certificates.generate_signing_ca: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.CACertificates().SignSigningCACSR(ctx, exampleID, SignIntermediateCSRRequest{CSRPEM: "example", ParentCAID: exampleID, ValidityDays: 1}); err == nil {
		t.Errorf("ca_certificates.sign_signing_ca_csr: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.EmailConfig().GetOrg(ctx); err == nil {
		t.Errorf("email_config.get_org: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.EmailConfig().SetOrg(ctx, SetOrgEmailConfig{Enabled: true, FromEmail: "example", FromName: "example", Provider: ProviderConfig{Kind: "smtp", Host: ptr("example"), Port: ptr(1), Starttls: ptr(true), Username: ptr("example")}}); err == nil {
		t.Errorf("email_config.set_org: expected a client-side refusal with no resolved context")
	}
	if err := anonymous.EmailConfig().DeleteOrg(ctx); err == nil {
		t.Errorf("email_config.delete_org: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.EmailConfig().TestOrg(ctx); err == nil {
		t.Errorf("email_config.test_org: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.EmailConfig().GetTenant(ctx); err == nil {
		t.Errorf("email_config.get_tenant: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.EmailConfig().SetTenant(ctx, EmailConfigOverride{}); err == nil {
		t.Errorf("email_config.set_tenant: expected a client-side refusal with no resolved context")
	}
	if err := anonymous.EmailConfig().DeleteTenant(ctx); err == nil {
		t.Errorf("email_config.delete_tenant: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.EmailConfig().TestTenant(ctx); err == nil {
		t.Errorf("email_config.test_tenant: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.Settings().GetOrg(ctx); err == nil {
		t.Errorf("settings.get_org: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.Settings().SetOrg(ctx, SetOrgSettings{AccessTokenLifetimeSecs: 1, AdminNotificationsEnabled: true, DefaultCertValidityDays: 1, EmailVerificationGracePeriodHours: 1, EmailVerificationRequired: true, HibpCheckEnabled: true, LockoutBackoffMultiplier: 1, LockoutDurationSecs: 1, MaxCertValidityDays: 1, MaxFailedLoginAttempts: 1, MaxLockoutDurationSecs: 1, MFAChallengeLifetimeSecs: 1, MFAEnforced: true, MinLength: 1, PasswordHistoryCount: 1, RefreshTokenLifetimeSecs: 1, RequireDigits: true, RequireLowercase: true, RequireSymbols: true, RequireUppercase: true}); err == nil {
		t.Errorf("settings.set_org: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.Settings().GetTenantOverride(ctx); err == nil {
		t.Errorf("settings.get_tenant_override: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.Settings().SetTenantOverride(ctx, TenantSettingsOverride{}); err == nil {
		t.Errorf("settings.set_tenant_override: expected a client-side refusal with no resolved context")
	}
	if err := anonymous.Settings().DeleteTenantOverride(ctx); err == nil {
		t.Errorf("settings.delete_tenant_override: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.WebauthnPolicy().Get(ctx); err == nil {
		t.Errorf("webauthn_policy.get: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.WebauthnPolicy().Set(ctx, WebauthnAttestationPolicy{BlockRevokedStatus: true, Mode: AttestationModeNone, RequireFidoCertified: true}); err == nil {
		t.Errorf("webauthn_policy.set: expected a client-side refusal with no resolved context")
	}
	if _, err := anonymous.WebauthnPolicy().ComplianceReport(ctx); err == nil {
		t.Errorf("webauthn_policy.compliance_report: expected a client-side refusal with no resolved context")
	}
	if got := srv.totalCalls(); got != before {
		t.Fatalf("expected zero wire calls, %d were made", got-before)
	}
}

