// TestGeneratedSecretFieldsAreSensitive is §27.5: every field the registry marks secret exists on its model and
// is a Sensitive.
//
// A generated model that silently dropped one would still pass every
// path-and-status case above — the call reaches the right route and the
// secret is simply absent — which is exactly how a one-time credential
// goes missing.
func TestGeneratedSecretFieldsAreSensitive(t *testing.T) {
	sensitiveType := reflect.TypeOf(Sensitive(""))
	for _, tc := range []struct {
		model         any
		schema, field string
	}{
		{CreateFederationConfigRequest{}, "CreateFederationConfigRequest", "client_secret"},
		{CreateSCIMTokenResponse{}, "CreateScimTokenResponse", "provisioning_token"},
		{CreateUserRequest{}, "CreateUserRequest", "password"},
		{CreateWebhookRequest{}, "CreateWebhookRequest", "secret"},
		{GeneratedCACertificate{}, "GeneratedCaCertificate", "private_key_pem"},
		{GeneratedCertificate{}, "GeneratedCertificate", "private_key_pem"},
		{GeneratedPGPKey{}, "GeneratedPgpKey", "private_key_armored"},
		{ImportCACertificateRequest{}, "ImportCaCertificateRequest", "private_key_pem"},
		{OAuth2ClientCreatedResponse{}, "OAuth2ClientCreatedResponse", "client_secret"},
		{RotateSecretResponse{}, "RotateSecretResponse", "client_secret"},
		{ServiceAccountCreatedResponse{}, "ServiceAccountCreatedResponse", "client_secret"},
		{UpdateFederationConfigRequest{}, "UpdateFederationConfigRequest", "client_secret"},
		{UpdateWebhookRequest{}, "UpdateWebhookRequest", "secret"},
	} {
		typ := reflect.TypeOf(tc.model)
		var found *reflect.StructField
		for i := 0; i < typ.NumField(); i++ {
			f := typ.Field(i)
			tag := f.Tag.Get("json")
			if name, _, _ := strings.Cut(tag, ","); name == tc.field {
				found = &f
				break
			}
		}
		if found == nil {
			t.Errorf("%s: the registry marks %q secret, but the generated model has no such field",
				tc.schema, tc.field)
			continue
		}
		got := found.Type
		if got.Kind() == reflect.Pointer {
			got = got.Elem()
		}
		if got != sensitiveType {
			t.Errorf("%s.%s is %s, not Sensitive: it would be logged in the clear",
				tc.schema, tc.field, found.Type)
		}
	}
}

// TestGeneratedSurfaceCoversTheRegistry is §27.9: a partial regeneration must fail here, not ship 140 of 147.
//
// Asserting the whole set rather than the count catches a regeneration
// that dropped one operation and gained another.
func TestGeneratedSurfaceCoversTheRegistry(t *testing.T) {
	expected := expectedSurface(t)
	if len(generatedSurface) != 147 {
		t.Fatalf("generated surface has %d operations, registry declares 147", len(generatedSurface))
	}
	if len(generatedSurface) != len(expected) {
		t.Fatalf("generated %d operations, registry declares %d", len(generatedSurface), len(expected))
	}
	for i := range expected {
		if generatedSurface[i] != expected[i] {
			t.Fatalf("operation %d: generated %q, registry declares %q", i, generatedSurface[i], expected[i])
		}
	}
}
